    /*
     * Add to the SerialNumbers
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	OutboundAllocation
     */
    public OutboundAllocation addToSerialNumbers( UUID parentId, SerialNumber addTo ) {
	    LOGGER.info("handling AssignSerialNumbersToOutboundAllocationEvent - " );
	    
	    OutboundAllocation parentEntity = repository.findById(parentId).get();
	    SerialNumber child = registry.project( SerialNumber.class, addTo.getSerialNumberId());
	    
	    parentEntity.getSerialNumbers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the SerialNumbers
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	OutboundAllocation
     */
	public OutboundAllocation removeFromSerialNumbers( UUID parentId, SerialNumber removeFrom ) {
	    LOGGER.info("handling RemoveSerialNumbersFromOutboundAllocationEvent " );
	
	    OutboundAllocation parentEntity = repository.findById(parentId).get();
	    SerialNumber child = registry.project( SerialNumber.class, removeFrom.getSerialNumberId());
	    
	    parentEntity.getSerialNumbers().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



